-- 运行保障：流程版本、完整导出任务和接口失败告警聚合。
BEGIN;

CREATE TABLE IF NOT EXISTS "流程版本" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer NOT NULL,
    "版本号" integer NOT NULL,
    "状态" varchar(10) NOT NULL DEFAULT '草稿',
    "流程定义" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "变更说明" varchar(2000),
    "生效时间" timestamp without time zone,
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_流程版本" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_流程版本_模板版本" UNIQUE ("流程模板编号", "版本号"),
    CONSTRAINT "ck_流程版本_版本" CHECK ("版本号" > 0),
    CONSTRAINT "ck_流程版本_状态" CHECK ("状态" IN ('草稿','生效','停用'))
);

CREATE INDEX IF NOT EXISTS "ix_流程版本_模板状态"
    ON "流程版本" ("流程模板编号", "状态", "版本号" DESC);

CREATE TABLE IF NOT EXISTS "数据导出任务" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "导出范围" varchar(50) NOT NULL,
    "状态" varchar(10) NOT NULL DEFAULT '申请中',
    "文件路径" varchar(1000),
    "文件校验" varchar(128),
    "记录数" bigint,
    "错误信息" varchar(4000),
    "申请人编号" integer NOT NULL,
    "申请时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "完成时间" timestamp without time zone,
    CONSTRAINT "pk_数据导出任务" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_数据导出任务_范围" CHECK ("导出范围" IN ('完整数据库','业务数据','审计数据')),
    CONSTRAINT "ck_数据导出任务_状态" CHECK ("状态" IN ('申请中','生成中','已完成','失败','已取消')),
    CONSTRAINT "ck_数据导出任务_记录数" CHECK ("记录数" IS NULL OR "记录数" >= 0)
);

CREATE INDEX IF NOT EXISTS "ix_数据导出任务_申请人时间"
    ON "数据导出任务" ("申请人编号", "申请时间" DESC);

CREATE OR REPLACE VIEW "v_接口失败告警" AS
SELECT "请求路径", "请求方法", "响应状态",
       count(*)::bigint AS "失败次数",
       max("创建时间") AS "最近失败时间",
       min("创建时间") AS "最早失败时间",
       count(DISTINCT "人员编号")::bigint AS "涉及人员数"
  FROM "操作审计"
 WHERE "是否成功" = FALSE
   AND "创建时间" >= CURRENT_TIMESTAMP - INTERVAL '24 hours'
 GROUP BY "请求路径", "请求方法", "响应状态";

CREATE INDEX IF NOT EXISTS "ix_操作审计_失败时间"
    ON "操作审计" ("是否成功", "创建时间" DESC);

UPDATE "系统迁移版本"
   SET "版本" = 51,
       "脚本" = '001-051',
       "检查摘要" = '增加流程版本、数据导出任务和接口失败告警视图'
 WHERE "编号" = 1;

COMMIT;
